import{_ as t}from"./chunks/7.DkEsj_3r.js";import{_ as o,o as a,c as r,aa as i}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/cs/performedworks/5.jpg",n="/buildary-help-preview/media/cs/performedworks/1.jpg",g=JSON.parse('{"title":"SPP Outputs","description":"","frontmatter":{"title":"SPP Outputs","wiki":"en:performedworks:output_methods"},"headers":[],"relativePath":"en/performedworks/output_methods.md","filePath":"en/performedworks/output_methods.md","lastUpdated":1794388980000}'),p={name:"en/performedworks/output_methods.md"};function d(c,e,l,u,h,m){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="spp-outputs" tabindex="-1">SPP Outputs <a class="header-anchor" href="#spp-outputs" aria-label="Permalink to &quot;SPP Outputs&quot;">​</a></h1><p>The output generated by the Buildary application is the so-called Measurement Report for a specific period, which is approved by the contracting parties, i.e. between the client and contractor or between the contractor and subcontractor. Therefore, dozens of Measurement Reports can be generated for a single period and even a single project, depending on the number of subcontractors active on the project.</p><p>The output can be generated using the Printing and Exports icon in the Performed Works window.</p><div class="wiki-figure" style="--w:1200px;"><img src="'+s+'" alt="" loading="lazy"></div><p>This function allows you to export data to Excel or PDF. A Measurement Report is always exported for the selected period.</p><p>The export contains summary information for the project and building objects, as well as a complete list of budget items.</p><p>Information is provided for all levels in a format similar to that displayed in the application window.</p><p>The document header indicates whether the output can be used as a basis for invoicing. This depends on the status of the Measurement Report.</p><div class="wiki-figure" style="--w:1000px;"><img src="'+t+'" alt="" loading="lazy"></div><img src="'+n+'" alt="" loading="lazy"><p>The PDF report serves as the basis for invoicing or as an attachment to the invoice. The file contains metadata that can be used to facilitate the receipt and approval of incoming invoices in an ERP system.</p><p>For further details, please contact our consultants at <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a></p>',12)])])}const w=o(p,[["render",d]]);export{g as __pageData,w as default};
